import React from 'react';

import { useState } from "react";
import "./signup.css";

function SignUp() {
  const [username, setUsername] = useState("");
  const [password, setPassword] = useState("");
  const[confirmpassword,setConfirmpassword]=useState("");
  const [rememberMe, setRememberMe] = useState(false);
  const [showPassword, setShowPassword] = useState(false);

  const handleSubmit = (e) => {
    e.preventDefault();

    if (!username || !password) {
      alert("Please enter your username and password.");
      return;
    }

    console.log({
      username,
      password,
      rememberMe,
    });

    // Connect your backend login API here.
  };

  return (
    <div className="signup-page">
      <div className="background-illustration">
  <img src="/login-illustration.png" alt="" />
</div>
      <div className="signup-card">

        {/* Left illustration section */}
        <div className="illustration-section">
          <img
            src="/login-illustration.png"
            alt="Student management login illustration"
          />
        </div>

        {/* Right login section */}
        <div className="form-section">
          <h1>SignUp</h1>

          <form onSubmit={handleSubmit}>
            <div className="input-group">
              <label htmlFor="username">User Name</label>
              <input
                id="username"
                type="text"
                placeholder="Enter username"
                value={username}
                onChange={(e) => setUsername(e.target.value)}
              />
            </div>

            <div className="input-group">
              <label htmlFor="password">Password</label>

              <div className="password-wrapper">
                <input
                  id="password"
                  type={showPassword ? "text" : "password"}
                  placeholder="Enter password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />

                <div className="input-group">
              <label htmlFor="password">Confirm Password</label>

              <div className="password-wrapper">
                <input
                  id="password"
                //   type={showPassword ? "text" : "password"}
                  placeholder="confirm  password"
                  value={password}
                  onChange={(e) => setPassword(e.target.value)}
                />

                <button
                  type="button"
                  className="eye-button"
                  onClick={() => setShowPassword(!showPassword)}
                  aria-label={
                    showPassword ? "Hide password" : "Show password"
                  }
                >
                  {showPassword ? "🙈" : "👁"}
                </button>
              </div>
            </div>
            </div>
            </div>

            <div className="form-options">
              <label className="remember">
                <input
                  type="checkbox"
                  checked={rememberMe}
                  onChange={(e) => setRememberMe(e.target.checked)}
                />
                <span>Remember me</span>
              </label>

              {/* </div><a href="/forgot-password">Forgot Password?</a> */}
            </div>

            <button type="submit" className="SignUp-button">
              SignUp
            </button>
          </form>

          <div className="divider">
            <span></span>
            <p>OR</p>
            <span></span>
          </div>

          <p className="signup-text">
            already  have an account?{" "}
            <a href="/login.jsx">login</a>
          </p>
        </div>
      </div>
    </div>
  );
}

export default SignUp;
